import { ELEMENTS_BY_ENGINE } from '../../core/runtime_registry.mjs';
import { renderElement } from '../../core/universal_renderer.mjs';
import { compileGridLayout, findLargestEmptyRegion } from '../../core/grid_layout_engine.mjs';
import { prepareDataGrid, gridVirtualWindow } from '../../core/data_grid_engine.mjs';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const app=$('.preview-app');
const score=97.1; $('#auditScore').textContent=score.toFixed(1); $('#qualityLabel').textContent=`${score.toFixed(1)} / 100`;
const themes=['light','dark','corporate'];let themeIndex=0;$('#themeBtn').addEventListener('click',()=>{themeIndex=(themeIndex+1)%themes.length;app.dataset.theme=themes[themeIndex];$('#themeBtn').setAttribute('aria-label',`Theme: ${themes[themeIndex]}`)});
$$('.nav-tab').forEach(btn=>btn.addEventListener('click',()=>{const id=btn.dataset.panel;$$('.nav-tab').forEach(b=>b.classList.toggle('active',b===btn));$$('.panel').forEach(p=>p.classList.toggle('active',p.id===`panel-${id}`));if(id==='data')ensureGrid();if(id==='layout')renderLayout();if(id==='export')renderExport();window.scrollTo({top:0,behavior:'smooth'});}));

const engineFilter=$('#engineFilter');Object.keys(ELEMENTS_BY_ENGINE).forEach(engine=>engineFilter.insertAdjacentHTML('beforeend',`<option value="${engine}">${engine}</option>`));
function renderGallery(){const q=$('#gallerySearch').value.trim().toLowerCase(),chosen=engineFilter.value;let shown=0,html='';for(const [engine,names] of Object.entries(ELEMENTS_BY_ENGINE)){if(chosen!=='all'&&chosen!==engine)continue;const filtered=names.filter(n=>!q||n.toLowerCase().includes(q)||engine.toLowerCase().includes(q));if(!filtered.length)continue;shown+=filtered.length;html+=`<section class="engine-section" data-engine-section="${engine}"><div class="engine-heading"><h2>${engine}</h2><span>${filtered.length} component${filtered.length===1?'':'s'}</span></div><div class="gallery-grid">${filtered.map(name=>renderElement(name,engine,{tier:'95+ passed'})).join('')}</div></section>`;}$('#galleryRoot').innerHTML=html;$('#resultCount').textContent=`${shown} of 248 elements`;}
$('#gallerySearch').addEventListener('input',renderGallery);engineFilter.addEventListener('change',renderGallery);renderGallery();

const layoutItems=[{id:'Executive summary',col:0,row:0,colSpan:7,rowSpan:2},{id:'Hero KPI',col:7,row:0,colSpan:5,rowSpan:2},{id:'Trend chart',col:0,row:2,colSpan:8,rowSpan:3},{id:'Decision panel',col:8,row:2,colSpan:4,rowSpan:3},{id:'Source / note',col:0,row:5,colSpan:12,rowSpan:1}];
function fitStage(stage,w,h){const available=Math.min(stage.parentElement.clientWidth-24,1040),scale=Math.min(available/(w*78),520/(h*78),1);stage.style.width=`${w*78}px`;stage.style.height=`${h*78}px`;stage.style.transform=`scale(${scale})`;stage.parentElement.style.height=`${Math.max(340,h*78*scale+42)}px`;return scale;}
function regionForPage(w,h){return findLargestEmptyRegion({width:w,height:h},[{x:.35,y:.18,width:w-.7,height:.72},{x:.35,y:h-.52,width:w-.7,height:.32}],{padding:.08});}
function renderLayout(){const w=+$('#pageW').value||13.333,h=+$('#pageH').value||7.5,cols=Math.max(1,+$('#cols').value||12),rows=Math.max(1,+$('#rows').value||6),gap=Math.max(0,+$('#gap').value||.08);const stage=$('#slideStage');fitStage(stage,w,h);stage.querySelectorAll('.sim-item').forEach(x=>x.remove());const target=regionForPage(w,h);const adapted=layoutItems.map((x,i)=>({...x,col:Math.min(x.col,cols-1),row:Math.min(x.row,rows-1),colSpan:Math.max(1,Math.min(x.colSpan,cols-Math.min(x.col,cols-1))),rowSpan:Math.max(1,Math.min(x.rowSpan,rows-Math.min(x.row,rows-1)))}));let plan;try{plan=compileGridLayout({page:{width:w,height:h},targetRegion:target,columns:cols,rows, gap,items:adapted,allowOverlap:true});}catch(e){$('#layoutMeta').textContent=e.message;return}const targetEl=$('#slideTarget');Object.assign(targetEl.style,{left:`${target.x/w*100}%`,top:`${target.y/h*100}%`,width:`${target.width/w*100}%`,height:`${target.height/h*100}%`});for(const p of plan.placements){const d=document.createElement('div');d.className='sim-item';Object.assign(d.style,{left:`${p.x/w*100}%`,top:`${p.y/h*100}%`,width:`${p.width/w*100}%`,height:`${p.height/h*100}%`});d.innerHTML=`<b>${p.id}</b><span>${p.colSpan}×${p.rowSpan} · normalized ${p.nw.toFixed(2)}×${p.nh.toFixed(2)}</span>`;stage.appendChild(d);}$('#layoutMeta').innerHTML=`<span>Page <b>${w.toFixed(2)} × ${h.toFixed(2)} in</b></span><span>Target <b>${target.width.toFixed(2)} × ${target.height.toFixed(2)} in</b></span><span>Grid <b>${cols} × ${rows}</b></span><span>Fingerprint <b>${hash(plan.fingerprint)}</b></span>`;}
['pageW','pageH','cols','rows','gap'].forEach(id=>$(`#${id}`).addEventListener('change',renderLayout));$('#recompileBtn').addEventListener('click',renderLayout);
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}

let gridReady=false,gridModel=null,gridRows=null,gridRenderTimes=[];
function makeRows(){const tools=['ETCH-12','CVD-07','LITHO-03','CMP-09','DIFF-02','METAL-11'],chambers=['A','B','C','D'];return Array.from({length:100000},(_,i)=>({id:i+1,tool:tools[i%tools.length],chamber:chambers[(i*7)%4],status:i%23===0?'Watch':i%17===0?'Hold':'On track',yield:i%101===0?null:Math.round((91+(i*13%800)/100)*100)/100}));}
function gridRowHeight(){return innerWidth<=900?44:36;}
function ensureGrid(){if(gridReady){renderVirtualGrid();return}const t0=performance.now();gridRows=makeRows();gridModel=prepareDataGrid({rows:gridRows,columns:[{key:'id',type:'number'},{key:'tool',type:'text'},{key:'chamber',type:'text'},{key:'status',type:'text'},{key:'yield',type:'number'}],sort:{key:'id',direction:'asc'}});gridReady=true;$('#gridMeta').textContent=`100,000 rows prepared in ${(performance.now()-t0).toFixed(0)} ms`;const grid=$('#virtualGrid');grid.addEventListener('scroll',renderVirtualGrid,{passive:true});grid.addEventListener('keydown',e=>{const row=document.activeElement?.closest?.('.vg-row');if(!row||!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();let idx=+row.dataset.index;if(e.key==='ArrowDown')idx++;if(e.key==='ArrowUp')idx--;if(e.key==='Home')idx=0;if(e.key==='End')idx=gridModel.rowCount-1;idx=Math.max(0,Math.min(gridModel.rowCount-1,idx));grid.scrollTop=idx*gridRowHeight();requestAnimationFrame(()=>{renderVirtualGrid();document.querySelector(`.vg-row[data-index="${idx}"]`)?.focus()})});renderVirtualGrid();}
function rebuildGrid(){if(!gridReady)return;const filter=$('#gridFilter').value, [key,direction]=$('#gridSort').value.split(':');const t0=performance.now();gridModel=prepareDataGrid({rows:gridRows,columns:[{key:'id',type:'number'},{key:'tool',type:'text'},{key:'chamber',type:'text'},{key:'status',type:'text'},{key:'yield',type:'number'}],filter,sort:{key,direction}});$('#virtualGrid').scrollTop=0;$('#gridMeta').textContent=`${gridModel.rowCount.toLocaleString()} rows · query ${(performance.now()-t0).toFixed(1)} ms`;renderVirtualGrid();}
$('#gridFilter').addEventListener('input',rebuildGrid);$('#gridSort').addEventListener('change',rebuildGrid);$$('.vg-header button').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.sort,current=$('#gridSort').value;$('#gridSort').value=`${key}:${current===`${key}:asc`?'desc':'asc'}`;rebuildGrid()}));
let gridPool=[];
function ensureGridPool(body,count=72){if(gridPool.length)return;const frag=document.createDocumentFragment();for(let i=0;i<count;i++){const row=document.createElement('div');row.className='vg-row';row.setAttribute('role','row');row.tabIndex=-1;for(let c=0;c<5;c++){const cell=document.createElement('span');cell.setAttribute('role','gridcell');row.appendChild(cell);}frag.appendChild(row);gridPool.push(row);}body.appendChild(frag);}
function renderVirtualGrid(){if(!gridReady)return;const t0=performance.now(),grid=$('#virtualGrid'),headerH=42,rowH=gridRowHeight(),win=gridVirtualWindow(gridModel.rowCount,Math.max(0,grid.scrollTop-headerH),grid.clientHeight-headerH,rowH,8),body=$('#vgBody');body.style.height=`${win.totalHeight}px`;ensureGridPool(body,80);const activeIndex=Number(document.activeElement?.dataset?.index);for(let slot=0;slot<gridPool.length;slot++){const row=gridPool[slot],i=win.start+slot;if(i>=win.end){row.hidden=true;continue}const r=gridModel.rows[i],cells=row.children;row.hidden=false;row.dataset.index=String(i);row.setAttribute('aria-rowindex',String(i+2));row.tabIndex=i===activeIndex?0:-1;row.style.transform=`translateY(${i*rowH}px)`;row.style.height=`${rowH}px`;cells[0].textContent=String(r.id);cells[1].textContent=r.tool;cells[2].textContent=r.chamber;cells[3].innerHTML=`<span class="state ${r.status==='On track'?'good':'warn'}">${r.status}</span>`;cells[4].textContent=r.yield==null?'Missing':r.yield.toFixed(2)+'%';cells[4].className=r.yield==null?'vg-null':'';}const dt=performance.now()-t0;if(gridRenderTimes.length>4)gridRenderTimes.push(dt);else gridRenderTimes.push(dt);if(gridRenderTimes.length>120)gridRenderTimes.shift();const sample=gridRenderTimes.length>5?gridRenderTimes.slice(2):gridRenderTimes,sorted=[...sample].sort((a,b)=>a-b),p95=sorted[Math.floor((sorted.length-1)*.95)]||dt;$('#gridMeta').textContent=`${gridModel.rowCount.toLocaleString()} rows · ${win.count} visible / ${gridPool.length} retained rows · ${p95.toFixed(2)} ms p95`;}

function renderExport(){const w=13.333,h=7.5,stage=$('#exportStage');fitStage(stage,w,h);stage.querySelectorAll('.sim-item').forEach(x=>x.remove());const target=regionForPage(w,h);Object.assign($('#exportTarget').style,{left:`${target.x/w*100}%`,top:`${target.y/h*100}%`,width:`${target.width/w*100}%`,height:`${target.height/h*100}%`});const plan=compileGridLayout({page:{width:w,height:h},targetRegion:target,columns:12,rows:6,gap:.08,items:layoutItems});for(const p of plan.placements){const d=document.createElement('div');d.className='sim-item';Object.assign(d.style,{left:`${p.x/w*100}%`,top:`${p.y/h*100}%`,width:`${p.width/w*100}%`,height:`${p.height/h*100}%`});d.innerHTML=`<b>${p.id}</b><span>editable PPT object group</span>`;stage.appendChild(d);}}
window.addEventListener('resize',()=>{if($('#panel-layout').classList.contains('active'))renderLayout();if($('#panel-export').classList.contains('active'))renderExport();if(gridReady)renderVirtualGrid()});
